import{c as t,Q as r,j as a,m as d}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Supported hardware","description":"","frontmatter":{},"headers":[],"relativePath":"reference/supported-hardware.md","filePath":"reference/supported-hardware.md","lastUpdated":1788066548000}'),o={name:"reference/supported-hardware.md"};function i(c,e,n,s,l,p){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="supported-hardware" tabindex="-1">Supported hardware <a class="header-anchor" href="#supported-hardware" aria-label="Permalink to &quot;Supported hardware&quot;">​</a></h1><p>VideoNode runs on any Linux host with a GPU and a V4L2 capture device. Hardware acceleration is currently tuned to Rockchip rk35xx; everywhere else it uses portable software backends. This page lists what each pipeline stage needs and what is validated today.</p><h2 id="support-matrix" tabindex="-1">Support matrix <a class="header-anchor" href="#support-matrix" aria-label="Permalink to &quot;Support matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Hardware-accelerated (Rockchip rk35xx today)</th><th>Portable software (any Linux GPU host)</th></tr></thead><tbody><tr><td>MJPEG decode</td><td>MPP (<code>librockchip-mpp</code>)</td><td>TurboJPEG</td></tr><tr><td>Color conversion (CSC)</td><td>RGA (<code>librga</code>)</td><td>libplacebo (Vulkan/GL)</td></tr><tr><td>H.264 / H.265 encode</td><td><code>h264_rkmpp</code> / <code>hevc_rkmpp</code></td><td><code>libx264</code> / <code>libx265</code>, or <code>*_vaapi</code></td></tr><tr><td>GPU compositing</td><td>Mali via the <code>panthor</code> DRM render node</td><td>any DRM render node libplacebo can open</td></tr></tbody></table><p>The accelerated column is what the packaged build targets today. The software column runs anywhere VideoNode is built from source against a working GPU.</p><h2 id="validated-platform" tabindex="-1">Validated platform <a class="header-anchor" href="#validated-platform" aria-label="Permalink to &quot;Validated platform&quot;">​</a></h2><ul><li><strong>Board:</strong> any Rockchip RK3588 board. The reference and recommended board is the <a href="https://www.friendlyelec.com/index.php?route=product/product&amp;product_id=292" target="_blank" rel="noreferrer">FriendlyElec NanoPC-T6</a> (including the T6 LTS), which the encoder paths are tuned against. Other RK35xx SoCs likely work but are not validated.</li><li><strong>OS:</strong> Debian 13 (trixie) or newer. The packaged native binaries link trixie-era shared libraries, so <code>apt</code> refuses to install on bookworm or older.</li><li><strong>Architecture:</strong> the APT package is <code>arm64</code> only. Other architectures require <a href="./../development/building">building from source</a>.</li></ul><h2 id="minimum-requirements" tabindex="-1">Minimum requirements <a class="header-anchor" href="#minimum-requirements" aria-label="Permalink to &quot;Minimum requirements&quot;">​</a></h2><ul><li>Linux with a DRM render node (<code>/dev/dri/renderD*</code>). The composer needs a GPU that libplacebo or RGA can drive.</li><li>A V4L2 capture device (<code>/dev/video*</code>) for live capture: USB UVC cameras, MIPI-CSI cameras, or HDMI capture cards. Verify with <code>v4l2-ctl --list-devices</code>. A test-mode source needs no device, so the pipeline can run hardware-free for dev or CI.</li><li>An <code>ffmpeg</code> on <code>PATH</code> with a working H.264 or H.265 encoder. Run <code>videonode validate-encoders</code> to confirm; see <a href="./../operating/encoders">Encoders</a> for the precedence rules.</li></ul><h2 id="led-status-indicators" tabindex="-1">LED status indicators <a class="header-anchor" href="#led-status-indicators" aria-label="Permalink to &quot;LED status indicators&quot;">​</a></h2><p>VideoNode can drive board status LEDs over sysfs when <code>led_control_enabled = true</code> (see <a href="./config-toml#features">config.toml reference</a>). With the gate off, the LED routes are not registered and the controller is a no-op.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Boards with a built-in driver</th><th>LED types exposed</th></tr></thead><tbody><tr><td>sysfs LED control</td><td>FriendlyElec NanoPC-T6</td><td><code>user</code>, <code>system</code></td></tr><tr><td>sysfs LED control</td><td>Orange Pi</td><td><code>blue</code>, <code>green</code></td></tr><tr><td>sysfs LED control</td><td>Raspberry Pi</td><td><code>act</code></td></tr></tbody></table><p>The board is detected from <code>/proc/device-tree/model</code>. Any other board falls back to the no-op controller, so the API accepts requests but no LED changes.</p><p>When a supported board is present, the API exposes:</p><ul><li><code>POST /api/leds</code>: set a LED&#39;s <code>type</code>, <code>enabled</code> state, and an optional <code>pattern</code>.</li><li><code>GET /api/leds/capabilities</code>: list the LED types and patterns this board supports.</li></ul><p>The supported patterns are <code>solid</code>, <code>blink</code>, and <code>heartbeat</code>.</p><p>To install on the validated platform, see <a href="./../getting-started/installation">Installing VideoNode</a>.</p>',17)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
